kind = {1:'assign',2:'assign',3:'cond',4:'assign',5:'assign',6:'goto',7:'return'}
target = {3:7, 6:2}
leaders = {1} | set(target.values()) | {s+1 for s in kind if kind[s] in ('goto','cond')}
leaders = sorted(leaders)
blocks = []
for idx, s in enumerate(leaders):
    end = leaders[idx+1]-1 if idx+1 < len(leaders) else 7
    blocks.append((s,end))
edges = set()
for idx,(s,e) in enumerate(blocks):
    k = kind[e]
    if k == 'goto':
        edges.add((s, target[e]))
    elif k == 'cond':
        edges.add((s, target[e]))
        edges.add((s, leaders[idx+1]))
    elif k == 'return':
        pass
    else:
        edges.add((s, leaders[idx+1]))
i = 1
tests = 0
body = 0
while True:
    tests += 1
    t1 = 4*i
    if t1 > 100:
        break
    body += 1
    i += 1
print(len(leaders))
print(len(blocks))
print(len(edges))
print(body)
print(tests)
